declare const limit: 10;
declare const count: number;
declare const sizes: 2 | 4;
for (let i = 0; i < limit - 1; i++) print(i);
for (let i = count; i < sizes; i++) print(i);
declare const items: string[];
for (let i = 0; i < 2.5; i++) print(i);
for (let i = 0; i < count + 0.5; i++) print(i);
for (let i = 0; i < 3; i++) print(i);
for (let i = 0; i < items.size(); i++) print(i);
for (let i = 0; i < items.indexOf("a"); i++) print(i);
